package ama.storage;
import ama.transcript.*;import ama.task.*;import ama.contract.TaskContracts.*;import java.util.*;import java.lang.reflect.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class Task10Fix01CapacityIT extends Task09MinutesFixture {
 @Override javax.sql.DataSource createSource(){return ama.minutes.Task10Source.open();}
 @Test void reservesRemainingAttemptsAndMergedSourceBeforeAdmission()throws Exception {
  confirmed();install();initialize(service(),"initial",3);var authority=ama.api.Task09RuntimeProbe.components(app).authority();var limits=new TranscriptAcquisitionBudget(16777216,16777216,16777216,268435456,134217728,8388608,128,256,2);var prep=new JdbcMinutesGenerationPreparation(authority,this::snapshot,pin,prompt,model,limits);var outbox=new JdbcOutbox(source,new MinutesEventReferences(source).validators());var actual=authority.minutesTaskPolicy();
  var filtered=(TaskDomainPolicy)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{TaskDomainPolicy.class},(p,m,args)->{if(m.getName().equals("prepare")&&((List<TaskSpec>)args[0]).stream().anyMatch(s->!meeting.equals(s.subject().id())))return Optional.empty();try{return m.invoke(actual,args);}catch(InvocationTargetException e){throw e.getCause();}});
  var queue=new JdbcTaskQueue(source,new JdbcSubjectFences(source,Set.of("MEETING")),outbox,Map.of("MINUTES_GENERATE_V1",filtered));var commands=new JdbcMinutesGenerationCommands(authority,prep,queue,outbox,new ama.audit.JdbcAuditAdapter(source));
  assertEquals(1,j.queryForObject("SELECT COUNT(*) FROM task_attempt a JOIN durable_task t ON t.id=a.task_id WHERE t.subject_id=?",Integer.class,meeting));
  var first=commands.enqueue(actor(),meeting,"last-admissible",4,UUID.randomUUID().toString());var before=state();var wider=new JdbcMinutesGenerationPreparation(authority,this::snapshot,pin,prompt,model,new TranscriptAcquisitionBudget(16777216,16777216,16777216,268435456,134217728,8388608,128,256,256));var widerCommands=new JdbcMinutesGenerationCommands(authority,wider,queue,outbox,new ama.audit.JdbcAuditAdapter(source));RuntimeException rejected=null;try{widerCommands.enqueue(actor(),meeting,"must-refuse",4,UUID.randomUUID().toString());}catch(RuntimeException e){rejected=e;}var after=state();
  // Settle only local, unmarked admitted tasks through real claim/completion, even on RED.
  var processed=new ArrayList<String>();for(int i=0;i<2;i++){var lease=queue.claim("MINUTES_GENERATE","FIX01_CAPACITY");if(lease.isEmpty())break;assertTrue(queue.complete(lease.orElseThrow(),new TaskResult(Outcome.FAILED,null,"LOCAL_BOUNDARY_PROBE")));processed.add(lease.orElseThrow().taskId());}
  assertTrue(processed.contains((String)((Map<?,?>)first.get("result")).get("taskId")));java.nio.file.Files.writeString(receipt.resolve("capacity-observation.json"),json.writeValueAsString(Map.of("bound",2,"sourceAttempts",1,"maxAttempts",3,"processed",processed,"refused",rejected!=null,"unchangedOnRefusal",before.equals(after))));
  assertNotNull(rejected,"Next admission must reserve new task plus retained merged source task before any writes");assertEquals(before,after,"Input/task/receipt/audit/outbox atomic refusal");
  String sourceRevision=j.queryForObject("SELECT transcript_revision_id FROM meeting WHERE id=?",String.class,meeting);isolated().mutate(actor(),meeting,"ordinary-shared-save",new ama.contract.TranscriptContracts.Command(ama.contract.TranscriptContracts.Operation.CONFIRM,4,sourceRevision,List.of()),UUID.randomUUID().toString());
 }
 Map<String,Object> state(){var result=new TreeMap<String,Object>();for(String table:List.of("generation_input","generation_candidate"))result.put(table,j.queryForList("SELECT * FROM "+table+" WHERE meeting_id=? ORDER BY id",meeting));result.put("tasks",j.queryForList("SELECT * FROM durable_task WHERE subject_id=? ORDER BY id",meeting));result.put("receipts",j.queryForList("SELECT * FROM idempotency_record WHERE resource_id=? ORDER BY scope_hash",meeting));result.put("audit",j.queryForList("SELECT * FROM audit_event WHERE resource_id=? ORDER BY id",meeting));result.put("outbox",j.queryForList("SELECT * FROM task_outbox WHERE subject_id=? ORDER BY sequence_id",meeting));return result;}
}
